1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: ath12k: fix build vs old compiler
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

gcc 11.4.1-3 warns about memcpy() with overlapping pointers:

drivers/net/wireless/ath/ath12k/wow.c: In function ‘ath12k_wow_convert_8023_to_80211.constprop’:
./include/linux/fortify-string.h:114:33: error: ‘__builtin_memcpy’ accessing 18446744073709551611 or more bytes at offsets 0 and 0 overlaps 9223372036854775799 bytes at offset -9223372036854775804 [-Werror=restrict]
  114 | #define __underlying_memcpy     __builtin_memcpy
      |                                 ^
./include/linux/fortify-string.h:637:9: note: in expansion of macro ‘__underlying_memcpy’
  637 |         __underlying_##op(p, q, __fortify_size);                        \
      |         ^~~~~~~~~~~~~
./include/linux/fortify-string.h:682:26: note: in expansion of macro ‘__fortify_memcpy_chk’
  682 | #define memcpy(p, q, s)  __fortify_memcpy_chk(p, q, s,                  \
      |                          ^~~~~~~~~~~~~~~~~~~~
drivers/net/wireless/ath/ath12k/wow.c:190:25: note: in expansion of macro ‘memcpy’
  190 |                         memcpy(pat, eth_pat, eth_pat_len);
      |                         ^~~~~~
./include/linux/fortify-string.h:114:33: error: ‘__builtin_memcpy’ accessing 18446744073709551605 or more bytes at offsets 0 and 0 overlaps 9223372036854775787 bytes at offset -9223372036854775798 [-Werror=restrict]
  114 | #define __underlying_memcpy     __builtin_memcpy
      |                                 ^
./include/linux/fortify-string.h:637:9: note: in expansion of macro ‘__underlying_memcpy’
  637 |         __underlying_##op(p, q, __fortify_size);                        \
      |         ^~~~~~~~~~~~~
./include/linux/fortify-string.h:682:26: note: in expansion of macro ‘__fortify_memcpy_chk’
  682 | #define memcpy(p, q, s)  __fortify_memcpy_chk(p, q, s,                  \
      |                          ^~~~~~~~~~~~~~~~~~~~
drivers/net/wireless/ath/ath12k/wow.c:232:25: note: in expansion of macro ‘memcpy’
  232 |                         memcpy(pat, eth_pat, eth_pat_len);
      |                         ^~~~~~

The sum of size_t operands can overflow SIZE_MAX, triggering the
warning.
Address the issue using the suitable helper.

Fixes: 4a3c212eee0e ("wifi: ath12k: add basic WoW functionalities")
Signed-off-by: Paolo Abeni <pabeni@redhat.com>
Reviewed-by: Kees Cook <kees@kernel.org>
Acked-by: Jeff Johnson <quic_jjohnson@quicinc.com>
Link: https://patch.msgid.link/3175f87d7227e395b330fd88fb840c1645084ea7.1721127979.git.pabeni@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by the potential overflow of size calculations when adding `eth_pkt_ofs` and `eth_pat_len`, which can lead to incorrect memory access in the `memcpy` function. This results in warnings from the compiler about overlapping pointers, as the sum of these operands can exceed the maximum value representable by `size_t`, leading to undefined behavior.

Here is the patch:
  */
 static void
 ath12k_wow_convert_8023_to_80211(struct ath12k *ar,
 				 const struct cfg80211_pkt_pattern *eth_pattern,
 				 struct ath12k_pkt_pattern *i80211_pattern)
 {
 	size_t r1042_eth_ofs = offsetof(struct rfc1042_hdr, eth_type);
 	size_t a1_ofs = offsetof(struct ieee80211_hdr_3addr, addr1);
 	size_t a3_ofs = offsetof(struct ieee80211_hdr_3addr, addr3);
 	size_t i80211_hdr_len = sizeof(struct ieee80211_hdr_3addr);
 	size_t prot_ofs = offsetof(struct ethhdr, h_proto);
 	size_t src_ofs = offsetof(struct ethhdr, h_source);
 	u8 eth_bytemask[WOW_MAX_PATTERN_SIZE] = {};
 	const u8 *eth_pat = eth_pattern->pattern;
 	size_t eth_pat_len = eth_pattern->pattern_len;
 	size_t eth_pkt_ofs = eth_pattern->pkt_offset;
 	u8 *bytemask = i80211_pattern->bytemask;
 	u8 *pat = i80211_pattern->pattern;
 	size_t pat_len = 0;
 	size_t pkt_ofs = 0;
 	size_t delta;
 	int i;

 	/* convert bitmask to bytemask */
 	for (i = 0; i < eth_pat_len; i++)
 		if (eth_pattern->mask[i / 8] & BIT(i % 8))
 			eth_bytemask[i] = 0xff;

 	if (eth_pkt_ofs < ETH_ALEN) {
 		pkt_ofs = eth_pkt_ofs + a1_ofs;

-		if (eth_pkt_ofs + eth_pat_len < ETH_ALEN) {
+		if (size_add(eth_pkt_ofs, eth_pat_len) < ETH_ALEN) {
 			memcpy(pat, eth_pat, eth_pat_len);
 			memcpy(bytemask, eth_bytemask, eth_pat_len);

 			pat_len = eth_pat_len;
 		} else if (eth_pkt_ofs + eth_pat_len < prot_ofs) {
 			memcpy(pat, eth_pat, ETH_ALEN - eth_pkt_ofs);
 			memcpy(bytemask, eth_bytemask, ETH_ALEN - eth_pkt_ofs);

 			delta = eth_pkt_ofs + eth_pat_len - src_ofs;
 			memcpy(pat + a3_ofs - pkt_ofs,
 			       eth_pat + ETH_ALEN - eth_pkt_ofs,
 			       delta);
 			memcpy(bytemask + a3_ofs - pkt_ofs,
 			       eth_bytemask + ETH_ALEN - eth_pkt_ofs,
 			       delta);

 			pat_len = a3_ofs - pkt_ofs + delta;
 		} else {
 			memcpy(pat, eth_pat, ETH_ALEN - eth_pkt_ofs);
 			memcpy(bytemask, eth_bytemask, ETH_ALEN - eth_pkt_ofs);

 			memcpy(pat + a3_ofs - pkt_ofs,
 			       eth_pat + ETH_ALEN - eth_pkt_ofs,
 			       ETH_ALEN);
 			memcpy(bytemask + a3_ofs - pkt_ofs,
 			       eth_bytemask + ETH_ALEN - eth_pkt_ofs,
 			       ETH_ALEN);

 			delta = eth_pkt_ofs + eth_pat_len - prot_ofs;
 			memcpy(pat + i80211_hdr_len + r1042_eth_ofs - pkt_ofs,
 			       eth_pat + prot_ofs - eth_pkt_ofs,
 			       delta);
 			memcpy(bytemask + i80211_hdr_len + r1042_eth_ofs - pkt_ofs,
 			       eth_bytemask + prot_ofs - eth_pkt_ofs,
 			       delta);

 			pat_len = i80211_hdr_len + r1042_eth_ofs - pkt_ofs + delta;
 		}
 	} else if (eth_pkt_ofs < prot_ofs) {
 		pkt_ofs = eth_pkt_ofs - ETH_ALEN + a3_ofs;

-		if (eth_pkt_ofs + eth_pat_len < prot_ofs) {
+		if (size_add(eth_pkt_ofs, eth_pat_len) < prot_ofs) {
 			memcpy(pat, eth_pat, eth_pat_len);
 			memcpy(bytemask, eth_bytemask, eth_pat_len);

 			pat_len = eth_pat_len;
 		} else {
 			memcpy(pat, eth_pat, prot_ofs - eth_pkt_ofs);
 			memcpy(bytemask, eth_bytemask, prot_ofs - eth_pkt_ofs);

 			delta = eth_pkt_ofs + eth_pat_len - prot_ofs;
 			memcpy(pat + i80211_hdr_len + r1042_eth_ofs - pkt_ofs,
 			       eth_pat +  prot_ofs - eth_pkt_ofs,
 			       delta);
 			memcpy(bytemask + i80211_hdr_len + r1042_eth_ofs - pkt_ofs,
 			       eth_bytemask + prot_ofs - eth_pkt_ofs,
 			       delta);

 			pat_len =  i80211_hdr_len + r1042_eth_ofs - pkt_ofs + delta;
 		}
 	} else {
 		pkt_ofs = eth_pkt_ofs - prot_ofs + i80211_hdr_len + r1042_eth_ofs;

 		memcpy(pat, eth_pat, eth_pat_len);
 		memcpy(bytemask, eth_bytemask, eth_pat_len);

 		pat_len = eth_pat_len;
 	}

 	i80211_pattern->pattern_len = pat_len;
 	i80211_pattern->pkt_offset = pkt_ofs;
 }



